package com.guillermomolina.protos.cli;
import com.guillermomolina.protos.execution.*;import com.guillermomolina.protos.parser.ParseError;import com.guillermomolina.protos.runtime.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;
public final class ProtosCli {private final ProtosValueRenderer renderer=new ProtosValueRenderer();public static void main(String[]a){int c=new ProtosCli().run(a,System.in,System.out,System.err);if(c!=0)System.exit(c);}public int run(String[]a,InputStream in,PrintStream out,PrintStream err){try{if(a.length==0)return repl(in,out,err);if(a.length==1&&(a[0].equals("--help")||a[0].equals("-h"))){help(out);return 0;}if(a.length==1&&(a[0].equals("--version")||a[0].equals("-v"))){String v=getClass().getPackage().getImplementationVersion();out.println("Protos "+(v==null?"development":v));return 0;}if(a[0].equals("-e")){if(a.length!=2)return usage(err,"-e requires exactly one source argument");return eval(a[1],session(),out,err);}if(a[0].startsWith("-"))return usage(err,"unknown option: "+a[0]);if(a.length!=1)return usage(err,"program arguments are not available yet: Core args is closure-invocation-only");String src;try{src=Files.readString(Path.of(a[0]),StandardCharsets.UTF_8);}catch(IOException e){err.println("protos: cannot read "+a[0]+": "+e.getMessage());return 1;}return eval(src,session(),out,err);}catch(Throwable e){err.println("Internal error: "+e);e.printStackTrace(err);return 70;}}private int repl(InputStream in,PrintStream out,PrintStream err)throws IOException{Session s=session();var r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));out.println("Protos REPL\nType :help for help, :quit to exit.");for(;;){out.print("protos> ");out.flush();String l=r.readLine();if(l==null){out.println();return 0;}if(l.isBlank())continue;if(l.equals(":quit")||l.equals(":exit"))return 0;if(l.equals(":help")){out.println(":help  show help\n:quit  exit\n:exit  exit\nTop-level context persists between evaluations.");continue;}eval(l,s,out,err);}}private Session session()throws IOException{Path c=core();ProtosPrelude p=new ProtosCoreBootstrap().bootstrap(c);return new Session(new ProtosSourceCompiler(),p.newModuleActivation());}private int eval(String src,Session s,PrintStream out,PrintStream err){try{out.println(renderer.render(s.c.compile(src).call(s.a)));return 0;}catch(ParseError e){err.println("Syntax error: "+e.getMessage());return 1;}catch(ProtosSignalException e){err.println("Error: "+renderer.render(e.error()));return 1;}catch(RuntimeException e){err.println("Runtime error: "+e.getMessage());return 1;}}private static Path core()throws IOException{String h=System.getenv("PROTOS_HOME");Path b=h==null||h.isBlank()?Path.of("").toAbsolutePath():Path.of(h);Path c=b.resolve("protos/lib/core");if(!Files.isDirectory(c))throw new IOException("cannot locate protos/lib/core; run via bin/protos or set PROTOS_HOME");return c;}private static int usage(PrintStream e,String m){e.println("protos: "+m+"\nTry 'protos --help'.");return 2;}private static void help(PrintStream o){o.println("Usage:\n  protos [file]\n  protos -e <source>\n  protos\n\nOptions:\n  -e <source>\n  -h, --help\n  -v, --version\n\nTop-level program args are not exposed: Core args is Closure-invocation-only.");}private record Session(ProtosSourceCompiler c,ProtosActivation a){}}
